import type { Chapter } from "../../core/types.js";

/** Returns chapters sorted by start time. */
export function sortChapters(chapters: readonly Chapter[]): readonly Chapter[] {
  return [...chapters].sort((left, right) => left.startTime - right.startTime);
}

/** Finds the chapter containing a timestamp. */
export function findChapterAt(chapters: readonly Chapter[], time: number): Chapter | null {
  const ordered = sortChapters(chapters);

  for (let index = 0; index < ordered.length; index += 1) {
    const chapter = ordered[index];

    if (chapter === undefined) {
      continue;
    }

    const end = chapter.endTime ?? ordered[index + 1]?.startTime ?? Number.POSITIVE_INFINITY;

    if (time >= chapter.startTime && time < end) {
      return chapter;
    }
  }

  return null;
}

/** Returns progress through a chapter in the inclusive 0–1 range. */
export function chapterProgress(chapter: Chapter, time: number): number {
  const end = chapter.endTime;

  if (end === undefined || end <= chapter.startTime) {
    return time >= chapter.startTime ? 1 : 0;
  }

  const progress = (time - chapter.startTime) / (end - chapter.startTime);
  return Math.min(Math.max(progress, 0), 1);
}

/** The chapter active at a timestamp, or the nearest previous chapter. */
export function activeChapterAt(chapters: readonly Chapter[], time: number): Chapter | null {
  return findChapterAt(chapters, time);
}

/** Returns the next chapter after a timestamp. */
export function nextChapter(chapters: readonly Chapter[], time: number): Chapter | null {
  const ordered = sortChapters(chapters);
  return ordered.find((chapter) => chapter.startTime > time + 0.001) ?? null;
}

/** Returns the previous chapter before (or containing) a timestamp. */
export function previousChapter(chapters: readonly Chapter[], time: number): Chapter | null {
  const ordered = sortChapters(chapters);
  const current = findChapterAt(ordered, time);

  if (current !== null) {
    return current;
  }

  for (let index = ordered.length - 1; index >= 0; index -= 1) {
    const chapter = ordered[index];

    if (chapter !== undefined && chapter.startTime < time) {
      return chapter;
    }
  }

  return null;
}

/** A chapter marker positioned on a timeline. */
export interface ChapterMarker {
  readonly chapter: Chapter;
  /** Position in the inclusive 0–1 range. */
  readonly position: number;
}

/** Returns chapter marker positions for a timeline. */
export function chapterMarkers(
  chapters: readonly Chapter[],
  duration: number,
): readonly ChapterMarker[] {
  if (!Number.isFinite(duration) || duration <= 0) {
    return [];
  }

  return sortChapters(chapters)
    .filter((chapter) => chapter.startTime > 0 && chapter.startTime < duration)
    .map((chapter) => ({
      chapter,
      position: Math.min(Math.max(chapter.startTime / duration, 0), 1),
    }));
}
